import{_ as a,o as t,c as n,a2 as r}from"./chunks/framework.DbIb1qZn.js";const p=JSON.parse('{"title":"Architecture","description":"How Frensense turns source files into findings, from parsing to the program graph and the checkers.","frontmatter":{"title":"Architecture","description":"How Frensense turns source files into findings, from parsing to the program graph and the checkers."},"headers":[],"relativePath":"architecture/index.md","filePath":"architecture/index.md"}'),i={name:"architecture/index.md"};function s(o,e,l,c,h,d){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="architecture-overview" tabindex="-1">Architecture overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to &quot;Architecture overview&quot;">​</a></h1><p>Frensense is a compiler first and a checker second. Every source file is lowered to a small intermediate representation (IR), and all analysis runs on the program graph built from that IR, never on source text.</p><h2 id="the-pipeline" tabindex="-1">The pipeline <a class="header-anchor" href="#the-pipeline" aria-label="Permalink to &quot;The pipeline&quot;">​</a></h2><ol><li><strong>Parse and lower.</strong> Each language has a provider built on a <a href="https://tree-sitter.github.io/" target="_blank" rel="noreferrer">tree-sitter</a> grammar (TypeScript, JavaScript, Python, Go, Rust, C). A provider says which syntax nodes are functions, calls, assignments and so on, and the lowering turns them into the shared IR. The engine itself does not know any one language.</li><li><strong>Build the program graph.</strong> From the IR the engine builds def-use chains in SSA form, a call graph, a points-to analysis (Steensgaard), a model of heap objects and fields, memory SSA, and a sparse value-flow graph that links definitions to uses across functions.</li><li><strong>Look up knowledge.</strong> Sources, sinks, sanitizers and policies come from the built-in pack and any <a href="/bundles">bundle</a>. They are data, not code.</li><li><strong>Run the checkers.</strong> Taint analysis starts from each sink argument and walks the value-flow graph backward: what could feed this value? It stops at a source (report a finding), at a sanitizer (clean), or at a value the engine cannot see into (stay quiet and record it for <code>frensense --explain</code>). Other checkers handle memory safety, policy and hygiene. A finding is an exact source-to-sink path.</li></ol><p>Two pieces of reasoning sit on top of that graph:</p><ul><li><strong>Guards.</strong> Conditions such as an early return after a failed check, or a comparison against a literal, can mark a value as validated on the branch where the check held.</li><li><strong>Values.</strong> A small value analysis tracks constants and numeric ranges. The memory-safety and policy checks use it, and the taint analysis uses it to ignore branches that integer comparisons prove can never run.</li></ul><p>To keep large projects fast, the taint analysis first runs without call-site context and then re-checks only the functions on a candidate path with one level of call-site context.</p><h2 id="what-it-does-not-do-yet" tabindex="-1">What it does not do yet <a class="header-anchor" href="#what-it-does-not-do-yet" aria-label="Permalink to &quot;What it does not do yet&quot;">​</a></h2><p>Worth knowing when you read a clean scan:</p><ul><li><strong>Top-level code</strong> that is not inside a function (a script&#39;s own body, for instance) is not analysed.</li><li><strong>Types are not resolved.</strong> The engine matches calls by name and by the package a value was imported from. It does not yet know that a variable holds a particular class, so it cannot follow an interface to its implementation.</li><li><strong>Value tracking is narrow.</strong> Integer constants are folded, string constants are not, and a check against a named collection (<code>if x not in ALLOWED</code>) is not recognised as a guard.</li><li><strong>Library calls with no model</strong> pass taint through by default, which can produce false positives.</li></ul><p>These are the engine&#39;s current limits, and each is a candidate for a <a href="/challenges">challenge</a>.</p><h2 id="chapters" tabindex="-1">Chapters <a class="header-anchor" href="#chapters" aria-label="Permalink to &quot;Chapters&quot;">​</a></h2><ul><li><a href="/architecture/program-graph">The program graph</a></li><li><a href="/architecture/checkers">Checkers</a></li><li><a href="/architecture/blindness">Engine blindness</a></li><li><a href="/architecture/benchmarks">Benchmarks</a></li><li><a href="/bundles">Bundles (.frc)</a></li></ul>',13)])])}const g=a(i,[["render",s]]);export{p as __pageData,g as default};
